// The planning agent's system prompt (generated by scripts/gen-prompt.mjs) and its fixed refusal sentence.
import { readFileSync } from 'node:fs';

export const REFUSAL = 'Aqui eu só planejo mudanças na arquitetura desta base. Quer adicionar, alterar ou remover algo nela?';

export function loadPlanPrompt() {
  return readFileSync(new URL('./system-prompt.md', import.meta.url), 'utf8');
}
